def _invoke_browse(self, url: str, query: str, language: str) -> Any:
    """Call the browsing agent, adapting to ``browse`` or ``run`` signatures."""
    browse = getattr(self.browsing_agent, "browse", None)
    if callable(browse):
        try:
            return _call_tool(browse, url, query, language)
        except TypeError:
            # Some browsing agents expose browse(url, query) only.
            return _call_tool(browse, url, query)
    run = getattr(self.browsing_agent, "run", None)
    if callable(run):
        return _call_tool(run, [{"url": url, "query": query}], query)
    return None

def _gather_evidence(
    self, plan: Dict[str, Any], steps: Optional[List[Dict[str, Any]]] = None
) -> Dict[str, Any]:
    """Search + browse each sub-question, honouring the wall-clock budget."""
    if steps is None:
        steps = []
    subquestions = plan.get("subquestions") or []
    language = plan.get("target_language") or "en"
    budget = self.max_research_time_s
    top_k = max(1, int(self.search_top_k))

    start = time.time()
    items: Dict[str, Dict[str, Any]] = {}
    search_calls = 0
    browse_calls = 0
    search_successes = 0
    truncated = False

    def timed_out() -> bool:
        return budget is not None and (time.time() - start) > budget

    for subquestion in subquestions:
        if timed_out():
            truncated = True
            break
        query = (subquestion or "").strip()
        if not query:
            continue

        steps.append({"t": time.time(), "action": "search", "detail": query})
        search_calls += 1
        try:
            raw = _call_tool(self.search_tool.search, query)
        except Exception:
            raw = None
        results = _normalize_search_results(raw)
        if results:
            search_successes += 1

        for result in results[:top_k]:
            if timed_out():
                truncated = True
                break
            url = result["url"]
            steps.append({"t": time.time(), "action": "browse", "detail": url})
            browse_calls += 1
            try:
                browsed = self._invoke_browse(url, query, language)
            except Exception:
                browsed = None

            snippets = _as_snippets(browsed)
            if not snippets and result["snippet"]:
                snippets = [result["snippet"]]

            item = items.get(url)
            if item is None:
                item = {
                    "url": url,
                    "title": result["title"],
                    "language": language,
                    "snippets": [],
                    "supporting_subquestions": [],
                }
                items[url] = item
            for snippet in snippets:
                if snippet and snippet not in item["snippets"]:
                    item["snippets"].append(snippet)
            if query not in item["supporting_subquestions"]:
                item["supporting_subquestions"].append(query)

        if truncated:
            break

    return {
        "items": list(items.values()),
        "truncated": truncated,
        "search_calls": search_calls,
        "browse_calls": browse_calls,
        "search_successes": search_successes,
        "steps": steps,
    }

def run(self, question: str, metadata: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Plan, gather evidence, and return an answer plus a structured trace."""
    plan = self._plan_research(question, metadata)
    steps: List[Dict[str, Any]] = [
        {"t": time.time(), "action": "plan", "detail": question}
    ]
    evidence = self._gather_evidence(plan, steps)

