"""Evidence-acquisition tests for ResearchAgent (subtask 3).

Runnable directly (``python tests/test_research_agent_evidence.py``) or via
pytest. Uses stdlib only plus lightweight mock tools.
"""

import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import agents.research_agent as ra  # noqa: E402
from agents.research_agent import PLACEHOLDER_ANSWER, ResearchAgent  # noqa: E402


class _Message:
    def __init__(self, content):
        self.content = content


class _Choice:
    def __init__(self, content):
        self.message = _Message(content)


class _Response:
    def __init__(self, content):
        self.choices = [_Choice(content)]


class MockResearchLLM:
    def __init__(self, payload):
        self.model_name = "gpt-4.1"
        self.payload = payload

    def get_chat_completion_sync(self, messages, **kwargs):
        return _Response(self.payload)


class MockBrowsingLLM:
    model_name = "gpt-4.1-mini"


class MockSearchTool:
    """Returns deterministic results; optionally the same URLs for every query."""

    def __init__(self, duplicate=False):
        self.calls = []
        self.duplicate = duplicate

    def search(self, query):
        self.calls.append(query)
        if self.duplicate:
            urls = ["https://ex.com/a", "https://ex.com/b"]
        else:
            urls = [f"https://ex.com/{abs(hash(query)) % 1000}"]
        return [
            {"url": u, "title": f"Title {u}", "snippet": f"Snippet for {query}"}
            for u in urls
        ]


class MockBrowsingAgent:
    def __init__(self):
        self.calls = []

    def browse(self, url, query, language):
        self.calls.append((url, query, language))
        return f"Extracted for {url} in {language}"


def _agent(plan_dict, search_tool=None, browsing_agent=None, **kwargs):
    return ResearchAgent(
        MockResearchLLM(json.dumps(plan_dict)),
        MockBrowsingLLM(),
        search_tool or MockSearchTool(),
        browsing_agent or MockBrowsingAgent(),
        **kwargs,
    )


def _plan(language="en", subquestions=None, answer_type="list_of_facts"):
    return {
        "target_language": language,
        "subquestions": subquestions
        or [
            "search the web for the topic background",
            "what are the key figures and dates",
            "what do recent studies conclude",
        ],
        "expected_answer_type": answer_type,
        "must_search": True,
    }


def test_three_subquestions_trigger_search_and_browse():
    search = MockSearchTool()
    browse = MockBrowsingAgent()
    agent = _agent(_plan(), search_tool=search, browsing_agent=browse)
    evidence = agent._gather_evidence(_plan())

    assert evidence["search_calls"] >= 3
    assert len(search.calls) >= 3
    assert all(isinstance(q, str) and q.strip() for q in search.calls)
    assert evidence["browse_calls"] >= 1
    assert len(browse.calls) >= 1
    assert evidence["items"]
    for item in evidence["items"]:
        assert item["snippets"] and any(s.strip() for s in item["snippets"])
        assert item["language"] == "en"


def test_deduplication_by_url():
    search = MockSearchTool(duplicate=True)
    browse = MockBrowsingAgent()
    agent = _agent(_plan(), search_tool=search, browsing_agent=browse)
    evidence = agent._gather_evidence(_plan())

    urls = [item["url"] for item in evidence["items"]]
    assert len(urls) == len(set(urls)), "evidence URLs must be unique"
    assert set(urls) == {"https://ex.com/a", "https://ex.com/b"}
    for item in evidence["items"]:
        assert len(item["supporting_subquestions"]) >= 1


def test_time_budget_truncates_and_stops_calls():
    search = MockSearchTool()
    browse = MockBrowsingAgent()
    agent = _agent(_plan(), search_tool=search, browsing_agent=browse)

    class Clock:
        def __init__(self):
            self.t = 0.0

        def time(self):
            self.t += 100.0
            return self.t

    original = ra.time
    ra.time = Clock()
    try:
        agent.max_research_time_s = 250.0
        evidence = agent._gather_evidence(_plan())
    finally:
        ra.time = original

    assert evidence["truncated"] is True
    assert evidence["search_calls"] < 3
    assert len(search.calls) == evidence["search_calls"]
    assert evidence["browse_calls"] == 0


def test_chinese_plan_preserves_language_and_queries():
    search = MockSearchTool()
    browse = MockBrowsingAgent()
    plan = _plan(language="zh", subquestions=["\u641c\u7d22\u4e2d\u6587\u8d44\u6599", "\u67e5\u627e\u6700\u65b0\u7814\u7a76"])
    agent = _agent(plan, search_tool=search, browsing_agent=browse)
    evidence = agent._gather_evidence(plan)

    assert any("\u4e2d\u6587" in q for q in search.calls)
    assert all(lang == "zh" for _, _, lang in browse.calls)
    assert all(item["language"] == "zh" for item in evidence["items"])


def test_run_exposes_evidence_and_steps():
    plan = _plan()
    agent = _agent(plan)
    result = agent.run("What are the main applications of CRISPR in agriculture?", {})

    assert result["answer"] == PLACEHOLDER_ANSWER
    trace = result["trace"]
    assert "evidence" in trace and trace["evidence"]["items"]
    assert trace["plan"]["must_search"] is True
    assert trace["steps"]
    for step in trace["steps"]:
        assert set(step) >= {"t", "action", "detail"}
        assert step["action"] in {"plan", "search", "browse"}
    actions = [s["action"] for s in trace["steps"]]
    assert actions[0] == "plan"
    assert "search" in actions


def test_run_reports_retrieval_failure_when_search_fails():
    class FailingSearch:
        def search(self, query):
            return []

    agent = _agent(_plan(), search_tool=FailingSearch())
    result = agent.run("What is the capital of France?", {})
    assert "retrieval failure" in result["answer"].lower()
    assert result["trace"]["evidence"]["search_successes"] == 0


if __name__ == "__main__":
    test_three_subquestions_trigger_search_and_browse()
    test_deduplication_by_url()
    test_time_budget_truncates_and_stops_calls()
    test_chinese_plan_preserves_language_and_queries()
    test_run_exposes_evidence_and_steps()
    test_run_reports_retrieval_failure_when_search_fails()
    print("research agent evidence tests passed")

