def detect_language(text: str) -> str:
    """Return "zh" if the text contains CJK characters, else "en"."""
    if text and _CJK_RE.search(text):
        return "zh"
    return "en"


def _insufficient_answer(language: str) -> str:
    """Language-appropriate answer used when evidence cannot ground a response."""
    if language == "zh":
        return INSUFFICIENT_EVIDENCE_ANSWER_ZH
    return INSUFFICIENT_EVIDENCE_ANSWER_EN


def _sanitize_citations(text: str, valid_ids: set) -> str:
    """Drop any citation id that does not map to a real evidence item."""

    def replace(match: "re.Match") -> str:
        if f"S{match.group(1)}" in valid_ids:
            return match.group(0)
        return ""

    return _CITATION_RE.sub(replace, text or "")


def _format_evidence(items: List[Dict[str, Any]]) -> "tuple[List[str], Dict[str, Dict[str, Any]]]":
    """Render evidence items as citation-tagged lines plus an id->item map."""
    lines: List[str] = []
    source_map: Dict[str, Dict[str, Any]] = {}
    for index, item in enumerate(items, 1):
        sid = f"S{index}"
        source_map[sid] = item
        snippet = " ".join(s for s in (item.get("snippets") or []) if s)
        lines.append(f"[{sid}] {item.get('url', '')} :: {snippet}")
    return lines, source_map

