    """Use GPT-4.1 to write a grounded, cited answer from ``evidence``.

    Returns ``{"answer": str, "used_sources": list[str]}``. When the
    evidence is empty or truncated, returns an explicit insufficiency answer
    with no citations instead of fabricating content.
    """
    language = (plan or {}).get("target_language") or detect_language(question)
    items = evidence.get("items") if isinstance(evidence, dict) else None
    if not items or evidence.get("truncated"):
        return {
            "answer": _insufficient_answer(language),
            "used_sources": [],
            "insufficient": True,
        }

    lines, source_map = _format_evidence(items)
    user_block = (
        f"Original question: {question}\n"
        f"Research plan: {json.dumps(plan or {}, ensure_ascii=False)}\n"
        f"Target language: {language}\n"
        f"Evidence items:\n" + "\n".join(lines) + "\n\n"
        "Write the final answer now, in the target language, citing evidence "
        "ids such as [S1] for every verifiable factual claim."
    )
    messages = [
        {"role": "system", "content": SYSTEM_PROMPT_RESEARCH_SYNTHESIS},
        {"role": "user", "content": user_block},
    ]
    try:
        response = self.research_llm.get_chat_completion_sync(
            messages=messages, temperature=0.2, max_tokens=2000
        )
        raw_answer = _extract_content(response).strip()
    except Exception as exc:  # missing method, network error, etc.
        return {
            "answer": _insufficient_answer(language),
            "used_sources": [],
            "insufficient": True,
            "error": f"synthesis call failed: {exc}",
        }

    if not raw_answer:
        return {
            "answer": _insufficient_answer(language),
            "used_sources": [],
            "insufficient": True,
            "error": "empty synthesis response",
        }

    answer = _sanitize_citations(raw_answer, set(source_map))
    used_sources: List[str] = []
    for match in _CITATION_RE.finditer(answer):
        sid = f"S{match.group(1)}"
        if sid in source_map and sid not in used_sources:
            used_sources.append(sid)
    return {"answer": answer, "used_sources": used_sources}

