def _references_protected_dataset(text: str) -> bool:
    """True if ``text`` references a protected raw dev/test dataset file.

    Decodes URL-encoded and backslash variants before matching so that
    ``%2Fworkspace%2Fdatasets%2Fdev.json`` or ``datasets\\test.json`` are caught.
    """
    if not text:
        return False
    normalized = str(text)
    for _ in range(3):
        decoded = urllib.parse.unquote(normalized)
        if decoded == normalized:
            break
        normalized = decoded
    normalized = normalized.replace("\\", "/").lower()
    return any(name in normalized for name in PROTECTED_DATASET_FILENAMES)

